<?php
session_start();
if(empty($_SESSION['user_id'])){header('Location:/pages/login.php');exit;}
require_once __DIR__.'/../config/config.php';
$userId=(int)$_SESSION['user_id'];$role=$_SESSION['role']??'';$isBackOffice=in_array($role,['publisher_admin','shop_admin'],true);$active_menu='reviews';
if(empty($_SESSION['seller_review_csrf']))$_SESSION['seller_review_csrf']=bin2hex(random_bytes(24));
function canReplyReview(PDO $pdo,int $userId,string $type,int $sellerId):bool{if($type==='user')return$userId===$sellerId;if(!in_array($type,['publisher','shop'],true))return false;$table=$type==='publisher'?'publisher_staff':'shop_staff';$column=$type==='publisher'?'publisher_id':'shop_id';$stmt=$pdo->prepare("SELECT 1 FROM $table WHERE user_id=? AND $column=? LIMIT 1");$stmt->execute([$userId,$sellerId]);return(bool)$stmt->fetchColumn();}
$error='';$saved=(int)($_GET['saved']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){$reviewId=(int)($_POST['review_id']??0);$reply=trim((string)($_POST['seller_reply']??''));if(!hash_equals($_SESSION['seller_review_csrf'],(string)($_POST['csrf_token']??'')))$error='คำขอหมดอายุ กรุณาลองใหม่';elseif($reply===''||mb_strlen($reply)>2000)$error='กรุณาเขียนคำตอบไม่เกิน 2,000 ตัวอักษร';else{$stmt=$pdo->prepare('SELECT r.user_id,b.seller_type,b.seller_id,b.title FROM book_reviews r JOIN books b ON b.book_id=r.book_id WHERE r.review_id=?');$stmt->execute([$reviewId]);$target=$stmt->fetch(PDO::FETCH_ASSOC);if(!$target||!canReplyReview($pdo,$userId,$target['seller_type'],(int)$target['seller_id']))$error='คุณไม่มีสิทธิ์ตอบรีวิวนี้';else{$pdo->beginTransaction();try{$pdo->prepare('UPDATE book_reviews SET seller_reply=?,seller_reply_at=NOW(),seller_reply_user_id=? WHERE review_id=?')->execute([$reply,$userId,$reviewId]);$pdo->prepare("INSERT INTO notifications(user_id,title,message,notification_type,related_review_id,is_read,sent_via) VALUES(?,'ร้านค้าตอบกลับรีวิวของคุณ',?,'review',?,0,'web')")->execute([(int)$target['user_id'],'ร้านค้าตอบรีวิวสินค้า “'.$target['title'].'”',$reviewId]);$pdo->commit();header('Location:/pages/seller_review_management.php?saved='.$reviewId.'#review-'.$reviewId);exit;}catch(Throwable $e){$pdo->rollBack();throw$e;}}}}
$stmt=$pdo->prepare("SELECT r.*,b.title,b.seller_type,b.seller_id,COALESCE(NULLIF(u.display_name,''),u.email,'ลูกค้า') reviewer_name,u.profile_image FROM book_reviews r JOIN books b ON b.book_id=r.book_id JOIN users u ON u.user_id=r.user_id WHERE (b.seller_type='user' AND b.seller_id=?) OR (b.seller_type='publisher' AND b.seller_id IN(SELECT publisher_id FROM publisher_staff WHERE user_id=?)) OR (b.seller_type='shop' AND b.seller_id IN(SELECT shop_id FROM shop_staff WHERE user_id=?)) ORDER BY r.created_at DESC");$stmt->execute([$userId,$userId,$userId]);$reviews=$stmt->fetchAll(PDO::FETCH_ASSOC);
function manageAvatar(?string $v):?string{if(!$v)return null;if(preg_match('#^https?://#i',$v))return$v;$v=ltrim(str_replace('\\','/',$v),'/');return str_starts_with($v,'uploads/')?'/pages/'.$v:'/assets/image/'.$v;}
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>จัดการรีวิวร้าน - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css?v=<?= filemtime(__DIR__.'/../assets/css/styles.css') ?>"><style>*{box-sizing:border-box}.page{max-width:960px;margin:auto;padding:44px 24px 90px}.page.main{max-width:none;padding:42px 54px 90px;background:#fff8f4;min-height:100vh}h1{color:var(--secondary-color);margin-top:0}.sub{color:var(--text-muted);margin-bottom:25px}.review{padding:24px;border:1px solid #eadbd5;border-radius:18px;background:#fff;margin-bottom:16px}.head{display:flex;gap:14px;align-items:center}.avatar{width:48px;height:48px;border-radius:50%;object-fit:cover;background:#f8dfe8;display:grid;place-items:center}.stars{color:#df9c28}.book{color:#c26586}.review-text{line-height:1.7;margin:16px 0}.reply{padding:15px 18px;border-left:4px solid #d88daa;border-radius:8px;background:#fff6f9;margin:15px 0}.reply small{color:#a3667c}.form textarea{width:100%;min-height:90px;padding:13px;border:1px solid #ddcec8;border-radius:11px;font:inherit;resize:vertical}.form button{margin-top:10px;padding:11px 20px;border:0;border-radius:9px;background:var(--secondary-color);color:#fff;font:inherit;font-weight:700;cursor:pointer}.notice{padding:12px 15px;border-radius:10px;margin-bottom:18px}.ok{background:#eaf5e6;color:#47733e}.bad{background:#fde8e5;color:#a33}.empty{text-align:center;padding:80px;color:var(--text-muted)}@media(max-width:900px){.page.main{padding:30px 18px 70px}}</style></head><body><?php if($isBackOffice){include __DIR__.'/../components/sidebar.php';}else{require __DIR__.'/../components/header.php';}?><main class="page<?=$isBackOffice?' main':''?>"><h1>รีวิวจากลูกค้า</h1><p class="sub">ดูความคิดเห็นและตอบกลับลูกค้าที่ซื้อสินค้าจริงจากร้านของคุณ</p><?php if($error):?><div class="notice bad"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(!$reviews):?><div class="empty">ร้านของคุณยังไม่มีรีวิว</div><?php else:foreach($reviews as $r):?><article class="review" id="review-<?=(int)$r['review_id']?>"><?php if($saved===(int)$r['review_id']):?><div class="notice ok">บันทึกคำตอบเรียบร้อยแล้ว</div><?php endif;?><div class="head"><?php if($avatar=manageAvatar($r['profile_image'])):?><img class="avatar" src="<?=htmlspecialchars($avatar)?>" alt=""><?php else:?><div class="avatar"><?=htmlspecialchars(mb_substr($r['reviewer_name'],0,1))?></div><?php endif;?><div><strong><?=htmlspecialchars($r['reviewer_name'])?></strong> <span class="stars"><?=str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating'])?></span><div class="book"><?=htmlspecialchars($r['title'])?> · <?=date('d/m/Y',strtotime($r['created_at']))?></div></div></div><p class="review-text"><?=htmlspecialchars($r['review_text']?:'ให้คะแนนโดยไม่ได้เขียนข้อความเพิ่มเติม')?></p><?php if($r['seller_reply']):?><div class="reply"><strong>คำตอบจากร้าน</strong><p><?=nl2br(htmlspecialchars($r['seller_reply']))?></p><small><?=date('d/m/Y H:i',strtotime($r['seller_reply_at']))?></small></div><?php endif;?><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['seller_review_csrf'])?>"><input type="hidden" name="review_id" value="<?=(int)$r['review_id']?>"><textarea name="seller_reply" maxlength="2000" required placeholder="ขอบคุณสำหรับรีวิว หรือชี้แจงรายละเอียดเพิ่มเติม..."><?=htmlspecialchars($r['seller_reply']??'')?></textarea><button><?=$r['seller_reply']?'แก้ไขคำตอบ':'ตอบกลับรีวิว'?></button></form></article><?php endforeach;endif;?></main><?php if(!$isBackOffice)require __DIR__.'/../components/footer.php';?></body></html>
